function wireCityMap(){const points=document.querySelectorAll('.city-point');points.forEach(point=>{const x=parseFloat(point.style.getPropertyValue('--city-x'));point.classList.toggle('city-align-left',x<20);point.classList.toggle('city-align-right',x>75);point.addEventListener('click',()=>{const open=point.getAttribute('aria-expanded')!=='true';points.forEach(p=>p.setAttribute('aria-expanded','false'));point.setAttribute('aria-expanded',String(open));});point.addEventListener('keydown',e=>{if(e.key==='Escape')point.setAttribute('aria-expanded','false');});});}
function wirePageMotion(){if(window._vfcRevealObserver)window._vfcRevealObserver.disconnect();if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const blocks=document.querySelectorAll('.home-section,.home-stats,.home-copy,.home-art,.svc-task,.svc-panel,.svc-factors,.svc-products,.ref-section,.kb-guide-preview,.kb-partner-preview');const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}});},{threshold:0.08,rootMargin:'0px 0px -20px 0px'});blocks.forEach((block,i)=>{block.classList.add('reveal-ready');block.style.setProperty('--reveal-delay',i<2?`${i*90}ms`:'0ms');observer.observe(block);});window._vfcRevealObserver=observer;}
