const refAbout=()=>refWrap(`${refCrumb('О нас')}<section class="ref-hero"><div><h1>Помогаем разобраться в сертификации</h1><p>Изучаем продукцию, подбираем профильных исполнителей и сопровождаем оформление документов.</p>${refButton()}</div><img src="assets/about-laboratory.jpg" alt="Работа с продукцией и документами в лаборатории" width="980" height="560"></section><section class="ref-section ref-two"><div><h2>О компании VFC-TEST</h2><p>Каждое государство устанавливает свои нормы и требования к продукции. В России такие нормы прописаны в ГОСТах, технических регламентах, федеральных законах и других нормативных документах. Под сертификацией часто имеют в виду выдачу сертификата как конечный результат.</p></div><div><p>Каждое государство устанавливает свои нормы и требования к продукции. В России такие нормы прописаны в ГОСТах, технических регламентах, федеральных законах и других нормативных документах. Под сертификацией часто имеют в виду выдачу сертификата как конечный результат.</p></div></section>${knowledgePartnerPreview()}<section class="ref-section"><h2>Что делаем мы и наши партнеры</h2><div class="ref-two ref-partner-roles"><article><h3>Команда VFC-TEST</h3><ul><li>Изучаем задачу и исходные документы</li><li>Подбираем органы и лаборатории</li><li>Готовим и согласуем пакет документов</li><li>Координируем этапы и сообщаем о ходе работы</li></ul></article><article><h3>Профильные органы и лаборатории</h3><ul><li>Проводят испытания продукции</li><li>Оценивают соответствие требованиям</li><li>Принимают решения в рамках своей компетенции</li></ul></article></div></section><section class="ref-section"><h2>Кто ведет ваш проект</h2><div class="ref-three ref-project-roles">${[['01','Менеджер проекта','Ваш контакт по вопросам, срокам и следующим шагам.'],['02','Подготовка документов','Собираем сведения о товаре и согласуем состав пакета.'],['03','Координация испытаний','Подбираем профильных партнеров и согласуем процедуры.']].map(x=>`<article><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></section><section class="ref-section ref-two ref-partner-countries"><div><h2>Наши страны-партнеры</h2><h3>Партнеры в странах ЕАЭС</h3><p>Подбираем профильных исполнителей под продукцию и задачу. Согласуем условия и координируем взаимодействие.</p></div><div class="home-map partner-vector-map" aria-label="Страны-партнеры: Россия, Армения, Беларусь, Кыргызстан и Казахстан"><img src="assets/eaeu-partners.svg" alt="Векторная карта России, Армении, Беларуси, Кыргызстана и Казахстана" width="816" height="460" loading="lazy"><button type="button" class="city-point partner-country-point" style="--city-x:41.184%;--city-y:58.826%" aria-label="Россия" data-map-name="Россия" aria-expanded="false"><span class="city-dot"></span><span class="city-tooltip" role="tooltip">Россия</span></button><button type="button" class="city-point partner-country-point" style="--city-x:6.993%;--city-y:44.342%" aria-label="Беларусь" data-map-name="Беларусь" aria-expanded="false"><span class="city-dot"></span><span class="city-tooltip" role="tooltip">Беларусь</span></button><button type="button" class="city-point partner-country-point" style="--city-x:5.673%;--city-y:75.997%" aria-label="Армения" data-map-name="Армения" aria-expanded="false"><span class="city-dot"></span><span class="city-tooltip" role="tooltip">Армения</span></button><button type="button" class="city-point partner-country-point" style="--city-x:23.672%;--city-y:77.424%" aria-label="Казахстан" data-map-name="Казахстан" aria-expanded="false"><span class="city-dot"></span><span class="city-tooltip" role="tooltip">Казахстан</span></button><button type="button" class="city-point partner-country-point" style="--city-x:27.188%;--city-y:90.503%" aria-label="Кыргызстан" data-map-name="Кыргызстан" aria-expanded="false"><span class="city-dot"></span><span class="city-tooltip" role="tooltip">Кыргызстан</span></button></div></section><section class="ref-section"><h2>Наш офис</h2><div class="ref-two ref-office-photos"><img src="assets/office-photo.jpg" alt="Рабочее пространство VFC-TEST" loading="lazy"><a class="ref-office-link" href="#/contacts"><span>Москва, ул. Смольная 24а</span><strong>Будем рады встрече</strong><p>Согласуйте время визита с менеджером.</p><span class="home-link">Контакты и схема проезда →</span></a></div></section><section class="ref-section"><h2>Отзывы клиентов</h2><div class="ref-about-reviews"><div class="yandex-reviews-embed"><iframe src="https://yandex.ru/maps-reviews-widget/189945161397?comments" title="Отзывы о ВФК-ТЕСТ на Яндекс Картах" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe><a class="yandex-reviews-attribution" href="https://yandex.ru/maps/org/vfk_test/189945161397/" target="_blank" rel="noopener">Вфк-тест на карте Москвы — Яндекс Карты</a><a class="widget-direct-link" href="https://yandex.ru/maps/org/vfk_test/189945161397/reviews/" target="_blank" rel="noopener">Все отзывы на Яндекс Картах ↗</a></div></div></section>${refRequest()}`);
const refCategoryDetail=(id)=>{const d=refCategories.find(x=>x[0]===id);if(!d)return null;return refWrap(`${refCrumb(d[1],true)}<section class="ref-hero"><div><h1>${d[1]}</h1><p>Поможем определить необходимые документы, подобрать исполнителей и организовать оформление для выпуска, ввоза и продажи продукции.</p>${refButton('Получить предварительный расчет')}</div><img src="assets/category-${d[0]}.jpg" alt="${d[1]}"></section><section class="ref-section"><h2>С чего начать оформление</h2><p>Требования зависят от назначения, состава и характеристик продукции, изготовителя и условий поставки. Пришлите описание товара и имеющиеся документы — проверим исходные данные и предложим порядок работы.</p></section>${refFactors()}${refFaq()}${refMarket()}${refRequest()}`);};
function wireReferencePages(){if(typeof wireCategoryAI==='function')wireCategoryAI(refCategories);document.querySelectorAll('[data-history]').forEach(b=>b.addEventListener('click',()=>{const track=document.getElementById('ref-history-track');track.scrollBy({left:Number(b.dataset.history)*track.clientWidth*.7,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}));document.querySelectorAll('[data-review-scroll]').forEach(b=>b.addEventListener('click',()=>{const track=document.getElementById('ref-reviews-track');track.scrollBy({left:Number(b.dataset.reviewScroll)*track.clientWidth*.6,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}));}

function render(){if(window._vfcPhotoCleanup){window._vfcPhotoCleanup();window._vfcPhotoCleanup=null;}const app=document.getElementById('app');let path=decodeURIComponent(location.hash.replace(/^#\/?/,''));let [section,id]=path.split('/');if(!path||path==='')app.innerHTML=home();else if(section==='registry')app.innerHTML=registryPage(id);else if(section==='catalog'&&!id)app.innerHTML=refCatalog();else if(section==='catalog'&&id==='textile')app.innerHTML=refClothing();else if(section==='catalog'&&refCategories.some(x=>x[0]===id))app.innerHTML=refCategoryDetail(id);else if(section==='catalog'&&id==='footwear')app.innerHTML=`${pageHero('Обувь и аксессуары','Обувь и аксессуары','Определим требования к материалам, назначению и возрастной группе продукции.')}<section class="section"><div class="wrap">${formCard('Обсудить оформление документов')}</div></section>`;else if(section==='catalog'&&id)app.innerHTML=productPage(id);else if(['declaration','certification','voluntary'].includes(section))app.innerHTML=servicePage(section);else if(['privacy','terms','cookies'].includes(section))app.innerHTML=legalPage(section);else if(section==='specifications')app.innerHTML=specifications();else if(['services','pick-services'].includes(section))app.innerHTML=services();else if(section==='partners')app.innerHTML=partnershipPage();else if(section==='guide')app.innerHTML=knowledgeGuidePage();else if(section==='about')app.innerHTML=refAbout();else if(section==='how')app.innerHTML=refHow();else if(section==='marketplaces')app.innerHTML=marketplace();else if(section==='reviews')app.innerHTML=reviews();else if(section==='cases')app.innerHTML=cases();else if(section==='articles')app.innerHTML=articles();else if(section==='contacts')app.innerHTML=refContacts();else if(section==='request')app.innerHTML=request();else if(section==='select')app.innerHTML=select();else app.innerHTML=home();document.querySelector('.floating')?.classList.toggle('hidden',['select','request'].includes(section));document.getElementById('navlinks').classList.remove('open');document.querySelector('.registry-nav')?.removeAttribute('open');document.getElementById('menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);wireForms();wireRegistry();wireQuiz();wireCityMap();wireServices();wireReferencePages();wirePageMotion();if(typeof vfcApplyLanguage==='function')vfcApplyLanguage();if((section==='guide'&&id)||(section==='partners'&&id==='request'))requestAnimationFrame(()=>{const target=document.getElementById(section==='guide'?'guide-'+id:'partner-enquiry');target?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});}
function wirePhotoForm(form){
 const input=form.querySelector('[data-photo-input]'),list=form.querySelector('[data-photo-list]'),error=form.querySelector('[data-photo-error]'),result=form.querySelector('.success'),drop=form.querySelector('.photo-drop'),counter=form.querySelector('[data-photo-count]');let photos=[],draftUrl=null;const maxBytes=10*1024*1024;const allowed=new Set(['image/jpeg','image/png','image/webp']);
 function cleanDraft(){if(draftUrl){URL.revokeObjectURL(draftUrl);draftUrl=null;}result.replaceChildren();result.style.display='none';}
 function renderPhotos(){list.replaceChildren();counter.textContent=photos.length?`${photos.length} из 5 · ${(photos.reduce((n,p)=>n+p.file.size,0)/1024/1024).toFixed(1)} МБ`:'Можно добавить до 5 фото';photos.forEach((photo,i)=>{const item=document.createElement('li'),img=document.createElement('img'),name=document.createElement('span'),remove=document.createElement('button');img.src=photo.url;img.alt=photo.file.name;name.textContent=photo.file.name;remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','Удалить фото '+photo.file.name);remove.addEventListener('click',()=>{URL.revokeObjectURL(photo.url);photos.splice(i,1);cleanDraft();renderPhotos();});item.append(img,name,remove);list.append(item);});}
 function addFiles(files){cleanDraft();const errors=[];for(const file of files){if(!allowed.has(file.type)){errors.push('Выберите фото JPG, PNG или WEBP.');continue;}if(photos.some(p=>p.file.name===file.name&&p.file.size===file.size&&p.file.lastModified===file.lastModified))continue;if(photos.length>=5){errors.push('Можно прикрепить не больше 5 фото.');continue;}if(photos.reduce((n,p)=>n+p.file.size,0)+file.size>maxBytes){errors.push('Общий размер фото должен быть не больше 10 МБ.');continue;}photos.push({file,url:URL.createObjectURL(file)});}error.textContent=[...new Set(errors)].join(' ');input.value='';renderPhotos();}
 input.addEventListener('change',()=>addFiles(Array.from(input.files||[])));['dragenter','dragover'].forEach(event=>drop.addEventListener(event,e=>{e.preventDefault();drop.classList.add('is-dragging');}));['dragleave','drop'].forEach(event=>drop.addEventListener(event,e=>{e.preventDefault();drop.classList.remove('is-dragging');if(event==='drop')addFiles(Array.from(e.dataTransfer.files||[]));}));form.addEventListener('input',e=>{if(e.target!==input)cleanDraft();});
 form.addEventListener('submit',async e=>{e.preventDefault();if(await submitLeadForm(form,photos.map(p=>p.file))){photos.forEach(p=>URL.revokeObjectURL(p.url));photos=[];renderPhotos();error.textContent='';}});
 const previous=window._vfcPhotoCleanup;window._vfcPhotoCleanup=()=>{if(previous)previous();photos.forEach(p=>URL.revokeObjectURL(p.url));if(draftUrl)URL.revokeObjectURL(draftUrl);};renderPhotos();
}

function buildLeadBody(data,photoCount){return [vfcT('Здравствуйте!'),'',vfcT('Имя:')+' '+data.get('name'),vfcT('Контакт:')+' '+data.get('contact'),vfcT('Компания:')+' '+(data.get('company')||vfcT('не указана')),...(data.get('role')?[vfcT('Ваша роль в проекте')+': '+vfcT(data.get('role'))]:[]),vfcT('Категория:')+' '+vfcT(data.get('category')||'не указана'),vfcT('Запрос:')+' '+vfcT(data.get('service')||'Нужна консультация'),'',vfcT('Описание:')+'\n'+(data.get('message')||vfcT('не указано')),...(typeof photoCount==='number'?['',vfcT('Фото:')+' '+photoCount]:[])].join('\n');}
async function submitLeadForm(form,files=[]){
 if(form.dataset.submitting||!form.reportValidity())return false;
 const data=new FormData(form),result=form.querySelector('.success');
 data.set('_subject','Заявка с сайта VFC-TEST');data.set('source_page',location.href);data.set('photo_count',String(files.length));
 const contact=String(data.get('contact')||'').trim();if(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact))data.set('email',contact);
 files.forEach(file=>data.append('attachment',file,file.name));
 const controls=Array.from(form.querySelectorAll('input,select,textarea,button')),states=controls.map(c=>c.disabled),button=form.querySelector('[type=submit]'),label=button.textContent;
 form.dataset.submitting='true';form.setAttribute('aria-busy','true');controls.forEach(c=>c.disabled=true);button.textContent=vfcT('Отправляем…');result.style.display='block';result.textContent=vfcT('Отправляем…');
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);
 try{
  const response=await fetch('https://formspree.io/f/maeelyvj',{method:'POST',body:data,headers:{Accept:'application/json'},signal:controller.signal});
  const payload=await response.json().catch(()=>null);
  if(!response.ok||!payload||payload.errors||payload.error||payload.ok===false){
   const detail=JSON.stringify(payload||{});
   const message=/NO_FILE_UPLOADS|file uploads.*not|upgrade|paid plan/i.test(detail)?'Фото не отправлены: загрузка файлов недоступна в тарифе Formspree. Удалите фото и отправьте заявку или свяжитесь с нами.':response.status===429?'Слишком много заявок. Подождите немного и повторите отправку.':'Не удалось отправить заявку. Данные сохранены — попробуйте ещё раз или напишите на m1@vfc-test.ru.';
   throw new Error(message);
  }
  form.reset();result.textContent=vfcT('Заявка отправлена! Мы свяжемся с вами по указанным контактам.');return true;
 }catch(err){result.textContent=vfcT(err.name==='AbortError'?'Время ожидания истекло. Данные сохранены. Перед повторной отправкой проверьте, не пришло ли подтверждение.':err instanceof TypeError?'Нет связи с сервисом отправки. Данные сохранены — проверьте интернет и попробуйте ещё раз.':err.message);return false;}
 finally{clearTimeout(timer);controls.forEach((c,i)=>c.disabled=states[i]);button.textContent=label;delete form.dataset.submitting;form.removeAttribute('aria-busy');}
}
function wireForms(){document.querySelectorAll('.lead-form').forEach(form=>{form.action='https://formspree.io/f/maeelyvj';form.method='post';form.enctype='multipart/form-data';if(form.querySelector('[data-photo-input]')){wirePhotoForm(form);return;}form.addEventListener('submit',e=>{e.preventDefault();submitLeadForm(form);});});}

